  "type .*Driver|New.*Store|Get.*Driver|interface",
  "Connect.*Client|MemoServiceClient|use.*Memo|createMemo|listMemos",
  "webhook|Webhook|SSE|EventSource|Broadcast|runner|cron|scheduler|go run",
  "CREATE TABLE|INSERT INTO|filter|CEL|cel"
];
