const cmds = [
"rg -n 'rpc (CreateMemo|ListMemos|DeleteMemo|Transcribe)|service ' proto/api/v1",
"rg -n 'CreateMemo|ListMemos|DeleteMemo' server/router/api/v1 --glob '*.go'",
"rg -n 'GetUser\\(' --glob '*.go' --glob '!store/db/**'",
"rg -n 'type (Driver|.*Driver)|func New|NewDriver|NewStore' store --glob '*.go'",
"rg --files store/migration | sed -n '1,120p'",
"rg --files web/src | grep -E 'connect|memo|query|mutation|api' | head -100",
"rg -n 'New.*ServiceClient|Client\\(' web/src --glob '*.ts' --glob '*.tsx'",
"rg -n 'Serve|embed|FileServer|frontend' server web --glob '*.go'"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:8000})));
rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

