const cmds=[
"find store/migration/sqlite -type f -maxdepth 3 -print | sort",
"rg -n 'CREATE TABLE.*(memo|memo_relation|attachment|reaction|user)|INSERT INTO memo' store/migration/sqlite",
"rg -n 'store\\.Memo|\\*Memo|\\[\\]\\*Memo' --glob '*.go' --glob '!store/test/**' --glob '!server/router/api/v1/test/**'",
"rg -n 'func \\(s \\*APIV1Service\\) (CreateMemo|ListMemos|DeleteMemo)|DispatchMemo' server/router/api/v1/memo_service.go server/router/api/v1/memo_update_helpers.go",
"rg -n 'func \\(d \\*DB\\) (CreateMemo|ListMemos|DeleteMemo)|INSERT INTO memo|memo_relation|attachment' store/db/sqlite/memo.go store/db/postgres/memo.go",
"rg -n 'func \\(.*\\) GetUser\\(|GetUser\\(ctx' store/user.go server/router/api/v1 --glob '*.go' | grep -v test",
"rg -n 'engine|CompileToStatement|AppendConditions|cel\\.NewEnv|Parse' internal/filter store/db/*/memo.go",
"rg -n 'Run\\(|RunOnce|NewRunner|scheduler\\.' server/runner server --glob '*.go' | grep -v test"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:9000})));
rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

